'use strict';
const $ = (s, root=document) => root.querySelector(s);
const esc = x => String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const topicCount=n=>n+' '+(n%100>=11&&n%100<=14?'тем':n%10===1?'тема':n%10>=2&&n%10<=4?'темы':'тем');
const ICONS={arrow:'M4 12h16m-6-6 6 6-6 6',book:'M4 4h6a2 2 0 0 1 2 2v14a3 3 0 0 0-3-2H4V4Zm16 0h-6a2 2 0 0 0-2 2m0 14a3 3 0 0 1 3-2h5V4Z',formula:'M5 5h14M9 5l6 14M5 19h14',cards:'M7 7h13v14H7zM3 16V3h13',mic:'M9 5a3 3 0 0 1 6 0v6a3 3 0 0 1-6 0V5Zm-3 5v1a6 6 0 0 0 12 0v-1m-6 7v5m-4 0h8',calendar:'M4 5h16v16H4zM8 2v6m8-6v6M4 10h16',search:'m16 16 5 5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',menu:'M4 6h16M4 12h16M4 18h16',check:'m5 12 4 4L19 6',download:'M12 3v12m-5-5 5 5 5-5M4 15v6h16v-6',bulb:'M8 17c0-3-3-4-3-8a7 7 0 0 1 14 0c0 4-3 5-3 8H8Zm1 3h6m-5 3h4',close:'m5 5 14 14M5 19 19 5',clock:'M12 7v5l4 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z'};
const icon=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${ICONS[name]||ICONS.book}"/></svg>`;
let mathFailures=[];
function math(tex,display=false){try{if(!window.katex)throw new Error('KaTeX unavailable');return katex.renderToString(tex,{displayMode:display,throwOnError:true,strict:'ignore',trust:false,output:'htmlAndMathml'});}catch(e){mathFailures.push({tex,error:e.message});return `<span class="math-error">${esc(tex)}</span>`;}}
function rich(text){return String(text).split(/(\\\([\s\S]*?\\\))/g).map(s=>s.startsWith('\\(')?`<span class="inline-math">${math(s.slice(2,-2))}</span>`:esc(s)).join('');}
const KEY='colloquium.study.v1';
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const localDate=s=>new Date(s+'T12:00:00');
const plusDays=(s,n)=>{const d=localDate(s);d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const dayDifference=(a,b)=>Math.round((localDate(b)-localDate(a))/86400000);
const baseState=()=>({version:1,course:COURSES[0].id,progress:{},cards:{},plans:{},last:{},practice:{},practiceRuleVersion:1,largeText:false});
function validState(s){return s&&s.version===1&&typeof s.progress==='object'&&s.progress!==null&&typeof s.cards==='object'&&s.cards!==null&&typeof s.plans==='object'&&s.plans!==null&&typeof s.last==='object'&&s.last!==null;}
let storageOK=true, state;
try{const s=JSON.parse(localStorage.getItem(KEY)||'null');state=validState(s)?s:baseState();}catch(e){state=baseState();storageOK=false;}
if(!COURSES.some(c=>c.id===state.course))state.course=COURSES[0].id;
const course=()=>COURSES.find(c=>c.id===state.course)||COURSES[0];
const topicKey=t=>`${course().id}:${t.id}`;
const status=t=>Math.max(0,Math.min(3,Number(state.progress[topicKey(t)])||0));
const statusNames=['Не начинал','Изучаю','Повторить','Могу объяснить'];
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch(e){storageOK=false;toast('Не удалось сохранить на устройстве. Экспортируйте прогресс в настройках.');}}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>el.classList.remove('visible'),4500);}
let viewGroup='all',query='',studyTab='theory',flash=null,oral=null,timerId=null;
function route(){const [page,id,section]=location.hash.slice(1).split('/');return {page:page||'home',id,section};}
function link(page,id){return `#${page}${id?'/'+id:''}`;}
const navItems=[['home','book','Темы'],['formulas','formula','Формулы'],['cards','cards','Карточки'],['oral','mic','Устный ответ'],['plan','calendar','План'],['settings','check','Прогресс']];
function sideTopics(){const c=course(),r=route();return c.groups.map((g,i)=>`<div class="side-group">${esc(g)}</div>${c.topics.filter(t=>t.group===i).map(t=>`<a class="side-topic ${r.page==='topic'&&r.id===t.id?'active':''}" href="#topic/${t.id}" ${r.id===t.id?'aria-current="page"':''}><span class="num">${String(c.topics.indexOf(t)+1).padStart(2,'0')}</span><span>${esc(t.title)}</span><span class="status-dot s${status(t)}" title="${statusNames[status(t)]}"></span></a>`).join('')}`).join('');}
function shell(){const c=course(),r=route();document.title=`${r.page==='topic'?(c.topics.find(t=>t.id===r.id)?.title||'Тема'):c.title} · Физика`;
document.body.classList.toggle('large-text',!!state.largeText);
$('#app').innerHTML=`<div class="shell"><aside class="sidebar" aria-label="Темы коллоквиума" ${window.matchMedia('(max-width:900px)').matches?'inert':''}><button class="close-drawer" data-action="close-menu" aria-label="Закрыть список тем">${icon('close',15)}</button><a class="brand" href="#home"><span class="brand-mark">φ</span><span><strong>Физика</strong><small>Подготовка к коллоквиуму</small></span></a><label class="sr-only" for="course-select">Выбрать коллоквиум</label><select id="course-select" class="course-select">${COURSES.map(x=>`<option value="${esc(x.id)}" ${x.id===c.id?'selected':''}>${esc(x.title)} · ${topicCount(x.topics.length)}</option>`).join('')}</select><div class="side-label"><span>Ваши билеты</span><span>${c.topics.length}</span></div><div class="side-topics">${sideTopics()}</div><div class="side-footer">${icon('check',14)} Прогресс на этом устройстве</div></aside><div class="mobile-scrim" data-action="close-menu"></div><div class="workspace"><header class="topbar"><button class="icon-button menu-btn" data-action="menu" aria-label="Открыть список тем" aria-expanded="false">${icon('menu')}<span class="small">Список тем</span></button><nav class="topnav" aria-label="Основная навигация">${navItems.map(([p,i,n])=>`<a href="#${p}" class="${r.page===p||(p==='home'&&r.page==='topic')?'active':''}" ${r.page===p?'aria-current="page"':''}>${icon(i)}${n}</a>`).join('')}</nav><div class="top-extra"><button class="icon-button" data-action="large-text" aria-label="Увеличенный текст" aria-pressed="${!!state.largeText}"><span>Aа</span></button></div></header><main id="main" tabindex="-1" class="content"></main></div></div>`;
$('#course-select').addEventListener('change',e=>{state.course=e.target.value;save();flash=null;oral=null;query='';viewGroup='all';stopTimer();location.hash='home';render();});
}
const context=(label,badge='')=>`<div class="context"><div class="breadcrumbs"><a href="#home">${esc(course().subtitle||course().title)}</a><span>/</span><span>${esc(label)}</span></div>${badge}</div>`;
const footer=()=>`<footer class="footer"><span>Материалы и прогресс по вашему коллоквиуму</span><div class="footer-links"><a href="#sources">Источники</a><a href="#settings">Прогресс и помощь</a><a href="Механика-офлайн.html" download="Физика.html" data-action="offline">${icon('download',12)} Офлайн-версия</a></div></footer>`;
const searchField=(placeholder='Найти тему или понятие')=>`<label class="searchbox">${icon('search',15)}<span class="sr-only">${placeholder}</span><input type="search" id="search" placeholder="${placeholder}" value="${esc(query)}" autocomplete="off"></label>`;
const chips=()=>`<div class="group-chips" role="group" aria-label="Раздел курса"><button class="chip ${viewGroup==='all'?'active':''}" data-group="all" aria-pressed="${viewGroup==='all'}">Все темы</button>${course().groups.map((g,i)=>`<button class="chip ${String(i)===viewGroup?'active':''}" data-group="${i}" aria-pressed="${String(i)===viewGroup}">${esc(g)}</button>`).join('')}</div>`;
const matches=(t,q)=>JSON.stringify([t.title,t.intro,t.definitions,t.formulas,t.derivations,t.questions,t.learning]).toLocaleLowerCase('ru').includes(q.toLocaleLowerCase('ru'));
const filtered=()=>course().topics.filter(t=>(viewGroup==='all'||String(t.group)===viewGroup)&&matches(t,query));
function pendulum(){return `<div class="hero-art" aria-hidden="true"><svg viewBox="0 0 300 250"><defs><pattern id="dots" width="18" height="18" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r=".7" fill="#bec9b7"/></pattern><marker id="arrowhead" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0 0 6 3 0 6" fill="none" stroke="#a7734e"/></marker></defs><rect x="20" y="10" width="260" height="225" fill="url(#dots)"/><path d="M80 29h130M100 19l10 10m10-10 10 10m10-10 10 10m10-10 10 10m10-10 10 10" stroke="#869982" stroke-width="1.3"/><path d="M146 30v173" stroke="#9cae97" stroke-dasharray="4 5"/><path d="M67 177a168 168 0 0 0 165 0" fill="none" stroke="#adbba5" stroke-dasharray="4 5"/><path d="M146 30 220 180" stroke="#174d48" stroke-width="2"/><path d="M146 77a48 48 0 0 0 22-6" fill="none" stroke="#a7734e"/><circle cx="146" cy="30" r="4" fill="#174d48"/><circle cx="220" cy="180" r="16" fill="#174d48"/><circle cx="215" cy="174" r="3" fill="#bdd1bc"/><path d="M220 196v31" stroke="#a7734e" stroke-width="1.4" marker-end="url(#arrowhead)"/><text x="156" y="91" fill="#a7734e" font-family="Georgia" font-style="italic" font-size="19">θ</text><text x="193" y="101" fill="#174d48" font-family="Georgia" font-style="italic" font-size="19">l</text><text x="236" y="217" fill="#a7734e" font-family="Georgia" font-style="italic" font-size="16">mg</text></svg><span class="art-label">всё начинается с равновесия</span></div>`;}
function home(){const c=course(),learned=c.topics.filter(t=>status(t)===3).length,revisit=c.topics.filter(t=>status(t)===2).length,last=c.topics.find(t=>t.id===state.last[c.id]),next=last||c.topics.find(t=>status(t)!==3)||c.topics[0];
return `${context('Подготовка',`<span class="badge green">${icon('book',12)} ${topicCount(c.topics.length)} в одном месте</span>`)}<section class="hero"><div><div class="eyebrow">${esc(c.subtitle||'Коллоквиум по физике')}</div><h1>${esc(c.title)}</h1><p class="hero-copy">${c.topics.length} темы из вашей программы: объяснения, формулы с примерами, пошаговые выводы и задачи с решениями. Начните с темы или продолжите с места, где остановились.</p><div class="hero-actions"><a class="btn" href="#topic/${next.id}">${last?'Продолжить':'Начать подготовку'} ${icon('arrow',16)}</a><a class="btn text" href="#plan">Составить план</a></div></div>${pendulum()}</section><section class="summary-strip" aria-label="Ваш прогресс"><div class="progress-block"><div class="progress-title"><span>Могу объяснить без подсказки</span><strong>${learned} / ${c.topics.length}</strong></div><div class="progress-track" role="progressbar" aria-label="Самооценка знания тем" aria-valuenow="${learned}" aria-valuemin="0" aria-valuemax="${c.topics.length}"><div class="progress-fill" style="width:${learned/c.topics.length*100}%"></div></div><div class="small muted" style="margin-top:7px;font-size:10px">Ваша самооценка, а не оценка преподавателя</div></div><div class="stat"><strong>${c.groups.length}</strong><span>раздела в программе</span></div><div class="stat"><strong>${revisit||c.topics.reduce((n,t)=>n+t.questions.length+(t.learning?.practice?.length||0),0)}</strong><span>${revisit?'тем на повторение':'вопросов и задач'}</span></div></section><section><div class="section-head"><h2>Программа коллоквиума</h2>${searchField()}</div>${chips()}<div id="topic-results">${topicCards()}</div></section><div class="guide">${icon('bulb',23)}<div><h3>Как устроена каждая тема</h3><p>Теория объясняет понятия и формулы. «Откуда формулы» показывает, как их получить из законов. «Практика» помогает проверить понимание на вопросах и задачах. Для полного ответа используйте раздел «Устный ответ».</p></div></div>${footer()}`;}
function topicCards(){const list=filtered();return list.length?`<div class="topic-grid">${list.map(t=>`<a class="topic-card" href="#topic/${t.id}"><span class="card-number">${String(course().topics.indexOf(t)+1).padStart(2,'0')}</span><div><h3>${esc(t.title)}</h3><p>${esc(course().groups[t.group])} &nbsp;·&nbsp; ${statusNames[status(t)]}</p></div><span class="status-dot s${status(t)}" title="${statusNames[status(t)]}"></span></a>`).join('')}</div>`:'<div class="empty">Ничего не найдено. Попробуйте другое слово или раздел.</div>';}
const oralSummary=t=>`<section class="oral-summary"><div class="eyebrow">Каркас устного ответа</div><p>${rich(t.oral)}</p></section>`;
const formulaCards=t=>t.formulas.map((_,i)=>lessonFormula(t,i)).join('');
const mistakes=t=>`<aside class="warning-box"><h3>На этом легко ошибиться</h3><ul>${t.mistakes.map(m=>`<li>${rich(m)}</li>`).join('')}</ul></aside>`;
function topicPage(id){const c=course(),t=c.topics.find(t=>t.id===id);if(!t)return `${context('Тема не найдена')}<h1>Такой темы пока нет</h1><p class="tip">Откройте список тем вашего коллоквиума.</p><a href="#home" class="btn">К программе</a>${footer()}`;
state.last[c.id]=t.id;save();const index=c.topics.indexOf(t);
return `<a class="topic-return" href="#home">← Все темы коллоквиума</a>${context(c.groups[t.group],`<span class="badge">Билет ${String(index+1).padStart(2,'0')} / ${c.topics.length}</span>`)}<h1 class="page-title">${esc(t.title)}</h1><p class="page-intro">${rich(t.intro)}</p><div class="article-tools"><div class="tabs" role="group" aria-label="Материалы темы">${[['theory','Теория'],['derive','Откуда формулы'],['check','Практика']].map(([v,n])=>`<button data-tab="${v}" class="${studyTab===v?'active':''}" aria-pressed="${studyTab===v}">${n}</button>`).join('')}</div><label class="status-control">Моя готовность <select id="topic-status" data-topic="${t.id}">${statusNames.map((s,i)=>`<option value="${i}" ${status(t)===i?'selected':''}>${s}</option>`).join('')}</select></label></div><article class="article-body">${topicBody(t)}</article><div class="topic-pagination">${index>0?`<a href="#topic/${c.topics[index-1].id}">← ${esc(c.topics[index-1].title)}</a>`:''}${index<c.topics.length-1?`<a class="next" href="#topic/${c.topics[index+1].id}">${esc(c.topics[index+1].title)} →</a>`:'<a class="next" href="#oral">Попробовать устный ответ →</a>'}</div>${footer()}`;
}
function topicBody(t){return lessonBody(t,studyTab);}
function formulas(){return `${context('Справочник')}<h1 class="page-title">Справочник формул</h1><p class="page-intro">У каждой формулы есть название, физический смысл, условия, обозначения и пример применения. Чтобы увидеть пошаговое получение формулы, откройте тему → «Откуда формулы».</p><div class="section-head" style="margin-top:25px"><span class="small muted">${course().topics.reduce((n,t)=>n+t.formulas.length,0)} формул и связей</span>${searchField('Поиск по формулам и темам')}</div>${chips()}${course().symbols?.length?`<details class="symbols"><summary>Обозначения и единицы СИ</summary><dl>${course().symbols.map(([s,d])=>`<div><dt>${esc(s)}</dt><dd>${esc(d)}</dd></div>`).join('' )}</dl></details>`:''}<div id="formula-results">${formulaResults()}</div>${footer()}`;}
function formulaResults(){const topics=filtered();return topics.length?topics.map(t=>`<section class="article-section"><div class="section-head"><h2 style="font-size:22px">${String(course().topics.indexOf(t)+1).padStart(2,'0')}. ${esc(t.title)}</h2><a href="#topic/${t.id}" class="small">К теме →</a></div><div class="formulas">${formulaCards(t)}</div></section>`).join(''):'<div class="empty">Формулы не найдены. Попробуйте название темы или понятия.</div>';}
function shuffle(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function makeDeck(filter='all'){const deck=[];for(const t of course().topics){const all=[...t.questions.map(([q,a],i)=>({q,a,suffix:'q'+i})),...(t.learning?.practice||[]).map((p,i)=>({q:p.question,a:p.answer,suffix:'p'+i}))];for(const {q,a,suffix} of all){const id=topicKey(t)+':'+suffix;const review=state.cards[id];if(filter==='weak'&&status(t)!==2)continue;if(filter==='due'&&review?.due&&review.due>today())continue;deck.push({id,t,q,a});}}flash={filter,deck:shuffle(deck),index:0,revealed:false,known:0,again:0};}
function flashPage(){if(!flash)makeDeck('due');const f=flash,current=f.deck[f.index];return `${context('Активное повторение')}<h1 class="page-title">Карточки для самопроверки</h1><p class="page-intro">Сформулируйте ответ вслух, затем сравните с подсказкой. «Помню» отложит карточку на 1, 3 или 7 дней; «Повторить» оставит её на сегодня.</p><div class="mode-toolbar"><label class="small muted">Набор &nbsp;<select id="deck-filter"><option value="due" ${f.filter==='due'?'selected':''}>Пора повторить + новые</option><option value="all" ${f.filter==='all'?'selected':''}>Все вопросы (${course().topics.reduce((n,t)=>n+t.questions.length+(t.learning?.practice?.length||0),0)})</option><option value="weak" ${f.filter==='weak'?'selected':''}>Темы с отметкой «Повторить»</option></select></label><button class="btn secondary" data-action="shuffle">Перемешать заново</button></div><div class="flash-wrap">${current?`<div class="flash-progress"><span>Карточка ${f.index+1} из ${f.deck.length}</span><a href="#topic/${current.t.id}">Билет ${course().topics.indexOf(current.t)+1} →</a></div><div class="progress-track"><div class="progress-fill" style="width:${f.index/f.deck.length*100}%"></div></div><div class="flash-card" style="margin-top:17px"><div class="eyebrow">${esc(course().groups[current.t.group])}</div><h2>${rich(current.q)}</h2>${f.revealed?`<div class="flash-answer">${rich(current.a)}</div>`:'<p class="small muted">Сначала свой ответ. Потом подсказка.</p>'}</div><div class="flash-actions">${f.revealed?'<button class="btn secondary" data-grade="again">Нужно повторить</button><button class="btn" data-grade="known">Помню</button>':'<button class="btn" data-action="reveal">Показать ответ</button>'}</div>`:`<div class="flash-card"><div class="eyebrow">${f.deck.length?'Сессия завершена':'На сегодня свободно'}</div><h2>${f.deck.length?'Сессия завершена.':'В этом наборе пока нет карточек.'}</h2><p class="muted">${f.deck.length?`Помню: ${f.known} · Повторить: ${f.again}.<br>Отметки карточек не заменяют оценку всей темы.`:'Выберите «Все вопросы», чтобы повторить весь материал.'}</p><div class="flash-actions"><a class="btn secondary" href="#home">К темам</a><button class="btn" data-action="all-cards">Все вопросы</button></div></div>`}</div>${footer()}`;}
function gradeCard(value){if(!flash?.revealed)return;const card=flash.deck[flash.index];if(!card)return;const previous=state.cards[card.id]||{};let streak=Number(previous.streak)||0;if(value==='known'){streak=Math.min(streak+1,3);flash.known++;}else{streak=0;flash.again++;state.progress[topicKey(card.t)]=2;}
state.cards[card.id]={streak,due:plusDays(today(),[0,1,3,7][streak]),updated:today()};flash.index++;flash.revealed=false;save();render(false);}
function stopTimer(){if(timerId){clearInterval(timerId);timerId=null;}if(oral)oral.running=false;}
function newOral(id){stopTimer();const all=course().topics,t=id?all.find(t=>t.id===id):null;const chosen=t||all[Math.floor(Math.random()*all.length)];oral={topicId:chosen.id,remaining:120,duration:120,running:false,show:false,checks:[false,false,false,false,false,false]};}
const timeString=s=>`${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;
function oralPage(id){if(!oral||(id&&oral.topicId!==id))newOral(id);const t=course().topics.find(t=>t.id===oral.topicId);return `${context('Репетиция коллоквиума')}<h1 class="page-title">Устный ответ по билету</h1><p class="page-intro">Расскажите тему без конспекта. Затем откройте пример ответа: у каждого из шести пунктов будет конкретный ожидаемый ответ и отметка «Я это объяснил». Сравнивайте содержание и ход мысли; дословного совпадения не требуется.</p><label class="oral-ticket-label">Выбрать билет<select id="oral-ticket" ${oral.running?'disabled':''}>${course().topics.map((x,i)=>`<option value="${x.id}" ${x.id===t.id?'selected':''}>${i+1}. ${esc(x.title)}</option>`).join('')}</select></label><section class="oral-card"><div class="oral-top"><span class="badge green">Билет ${String(course().topics.indexOf(t)+1).padStart(2,'0')}</span><output class="timer" id="timer" aria-label="Осталось времени" aria-live="off">${timeString(oral.remaining)}</output></div><h2>${esc(t.title)}</h2><div class="mode-toolbar"><label class="small muted">Время &nbsp;<select id="oral-duration" ${oral.running?'disabled':''}>${[60,120,180].map(s=>`<option value="${s}" ${oral.duration===s?'selected':''}>${s/60} мин</option>`).join('')}</select></label><div class="flash-actions" style="margin:0"><button class="btn" data-action="timer">${oral.running?'Пауза':oral.remaining===0?'Начать заново':'Начать ответ'}</button><button class="btn secondary" data-action="new-ticket">Другой билет</button></div></div><p class="tip">Две минуты — ориентир для краткого рассказа. Подробный математический вывод можно проговорить отдельно, без таймера.</p><button class="btn secondary" data-action="oral-reveal">${oral.show?'Скрыть пример ответа':'Завершить и сравнить с примером'}</button>${oral.show?oralReference(t):''}</section>${footer()}`;}
function oralReference(t){const model=t.learning?.oralAnswer;if(!model)return '<div style="margin-top:20px">'+oralSummary(t)+'</div>';return `<section class="oral-reference"><h2>Пример правильного ответа</h2><p>Это готовый вариант рассказа по выбранному билету. Его можно произнести своими словами; формулы и объяснения ниже составляют сам ответ, а не список наводящих вопросов.</p><div class="oral-model-answer">${model.map((p,i)=>`<p><span class="oral-paragraph-number">${i+1}</span>${rich(p.answer)}</p>`).join('')}</div><h2 style="margin-top:28px">Сравните со своим рассказом</h2><p>Каждый пункт соответствует абзацу примера выше. Отметьте то, что успели объяснить самостоятельно; пропущенное повторите. Это самооценка содержания, а не автоматическая оценка речи.</p><div class="oral-score" id="oral-score">Объяснил самостоятельно: ${oral.checks.filter(Boolean).length} из ${model.length} пунктов</div>${model.map((p,i)=>`<article class="oral-criterion"><h3>${i+1}. ${esc(p.criterion)}</h3><label><input type="checkbox" data-oral-check="${i}" ${oral.checks[i]?'checked':''}>${esc(p.check)}</label></article>`).join('')}<div class="lesson-next"><p>Если пункт пока не получается, откройте его объяснение в теме и попробуйте ответить ещё раз.</p><div class="flash-actions" style="justify-content:flex-start"><a class="btn secondary" href="#topic/${t.id}/derive">Открыть выводы формул</a><a class="btn secondary" href="#topic/${t.id}/check">Закрепить на задачах</a><button class="btn" data-oral-status="3">Тему могу объяснить</button><button class="btn secondary" data-oral-status="2">Тему нужно повторить</button></div></div></section>`;}
function toggleTimer(){if(oral.running){stopTimer();render(false);return;}if(oral.remaining<=0)oral.remaining=oral.duration;oral.running=true;oral.deadline=Date.now()+oral.remaining*1000;render(false);timerId=setInterval(()=>{oral.remaining=Math.max(0,Math.ceil((oral.deadline-Date.now())/1000));const output=$('#timer');if(output)output.textContent=timeString(oral.remaining);if(!oral.remaining){stopTimer();toast('Время вышло. Закончите мысль и проверьте ответ.');render(false);}},250);}
function getPlan(){const c=course();let p=state.plans[c.id];if(!p||!/^\d{4}-\d{2}-\d{2}$/.test(p.start)||!Number.isFinite(+localDate(p.start))||!Number.isInteger(p.days)||p.days<3||p.days>60){p={start:today(),days:14};state.plans[c.id]=p;save();}return p;}
function planPage(){const p=getPlan(),c=course(),learnDays=Math.max(1,p.days-2),current=dayDifference(p.start,today());let days=[];for(let i=0;i<p.days;i++){const date=plusDays(p.start,i),items=i<learnDays?c.topics.slice(Math.floor(i*c.topics.length/learnDays),Math.floor((i+1)*c.topics.length/learnDays)):[];const review=i>=learnDays;days.push(`<article class="plan-day ${i===current?'today':''}"><div class="eyebrow">День ${i+1} · ${localDate(date).toLocaleDateString('ru-RU',{day:'numeric',month:'short'})}${i===current?' · сегодня':''}</div><h3>${review?(i===p.days-1?'Репетиция и лёгкое повторение':'Собрать картину целиком'):(items.length?'Разобрать и проговорить':'Закрепить изученное')}</h3>${items.length?`<ul>${items.map(t=>`<li><a href="#topic/${t.id}">${status(t)===3?'✓ ':''}${c.topics.indexOf(t)+1}. ${esc(t.title)}</a></li>`).join('')}</ul>`:''}<p class="small muted" style="margin-top:10px">${review?(i===p.days-1?'Случайные билеты без конспекта. Пройдите слабые места, затем отдых.':'Повторите ключевые формулы и выводы всех разделов. Сначала темы с отметкой «Повторить».'):'Начните с 5–10 минут повторения вчерашнего. Новые темы: теория → вывод на бумаге → вопросы вслух.'}</p></article>`);}
return `${context('Личный маршрут')}<h1 class="page-title">План подготовки</h1><p class="page-intro">Темы идут в порядке программы; последние два дня оставлены на повторение. Выберите срок и начальную дату. План — ориентир: сложной теме можно уделить больше времени.</p><div class="plan-settings"><label>Начать с<input type="date" id="plan-start" value="${p.start}" min="2020-01-01" max="2100-12-31"></label><label>Дней до коллоквиума<select id="plan-days">${[7,10,14,21,30,45,60,...(![7,10,14,21,30,45,60].includes(p.days)?[p.days]:[])].sort((a,b)=>a-b).map(n=>`<option value="${n}" ${p.days===n?'selected':''}>${n} дней</option>`).join('')}</select></label><button class="btn" data-action="save-plan">Обновить план</button></div><p class="tip">Ориентир: 30–60 минут в день на 14-дневном плане. Если вывод пока не получается, отметьте тему «Повторить». Это не расписание уведомлений.</p><div class="plan-list">${days.join('')}</div>${footer()}`;}
function sourcesPage(){return `${context('Об источниках')}<h1 class="page-title">Основа конспекта</h1><p class="page-intro">Самостоятельно составленный краткий материал по вашему списку из 23 вопросов. Ссылки ниже помогут углубиться и сверить детали; обозначения на сайте приведены к единой системе.</p>${SOURCES.map(s=>`<section class="source"><h3><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a></h3><p>${esc(s.note)}</p></section>`).join('')}<div class="guide">${icon('book',23)}<div><h3>Как пользоваться вместе с лекциями</h3><p>Сверяйте принятые преподавателем обозначения и объём вывода. Здесь классическая механика и стандартные модели. В затухании γ = b/(2m); расход жидкости обозначен qV, добротность — Q. Законы Ньютона, Паскаля и тяготения сформулированы как опытные основы; для них показаны следствия, а не фиктивные «доказательства».</p></div></div>${footer()}`;}
function settingsPage(){return `${context('Прогресс и помощь')}<h1 class="page-title">Прогресс и помощь</h1><section class="settings-card"><h2>Перенос прогресса между устройствами</h2><p class="small muted">На первом устройстве нажмите «Экспорт прогресса» и сохраните JSON-файл. Передайте его на другое устройство, откройте эту страницу и нажмите «Импорт прогресса». Перед заменой текущего прогресса приложение запросит подтверждение.</p><p class="small muted">Отметки тем, интервалы карточек и планы сохраняются в этом браузере. На другом устройстве они появятся после экспорта и импорта файла. Очистка данных браузера удаляет локальные отметки. В приватном режиме сохранение может быть временным.</p><p class="small muted" style="margin-top:10px">${storageOK?'Хранилище браузера доступно.':'Не удалось обратиться к хранилищу. Экспортируйте результаты перед закрытием.'}</p><div class="settings-actions"><button class="btn" data-action="export">Экспорт прогресса</button><button class="btn secondary" data-action="import">Импорт прогресса</button><input type="file" id="progress-file" accept="application/json,.json" hidden></div></section><section class="settings-card"><h2>Заберите приложение с собой</h2><p class="small muted">Скачайте один HTML-файл: в него уже включены материалы, интерфейс и отображение формул. На ПК откройте файл в браузере. На телефоне используйте браузер, поддерживающий открытие локальных HTML, или размещённую версию. Хранилище локального файла и сайта может различаться — переносите прогресс через экспорт.</p><div class="settings-actions"><a class="btn secondary" href="Механика-офлайн.html" download="Коллоквиум.html" data-action="offline">${icon('download',15)} Скачать офлайн-версию</a></div></section><section class="settings-card"><h2>Следующий коллоквиум</h2><p class="small muted">Приложение поддерживает несколько коллоквиумов. Для следующего пришлите новый список тем в этот чат: добавим отдельный курс с определениями, формулами, выводами и вопросами. Текущая механика и её прогресс сохранятся. Новые материалы не появляются автоматически.</p></section><section class="settings-card"><h2>Как готовиться</h2><p class="small muted">1. Прочитайте определения и условия. 2. Восстановите вывод на бумаге. 3. Ответьте на вопросы без подсказки. 4. Дайте полный устный ответ по каркасу. Статус темы меняйте самостоятельно; кнопка «Нужно повторить» на карточке также помечает тему для повторения.</p><div class="settings-actions"><button class="btn text" data-action="reset">Сбросить весь прогресс</button></div></section>${footer()}`;}
function render(scroll=true){const r=route();if(r.page==='topic')studyTab=['theory','derive','check'].includes(r.section)?r.section:'theory';if(r.page!=='oral')stopTimer();shell();const main=$('#main');if(r.page==='topic')main.innerHTML=topicPage(r.id);else if(r.page==='formulas')main.innerHTML=formulas();else if(r.page==='cards')main.innerHTML=flashPage();else if(r.page==='oral')main.innerHTML=oralPage(r.id);else if(r.page==='plan')main.innerHTML=planPage();else if(r.page==='sources')main.innerHTML=sourcesPage();else if(r.page==='settings')main.innerHTML=settingsPage();else main.innerHTML=home();bindPage();if(scroll){window.scrollTo(0,0);main.focus({preventScroll:true});}}
function updateSearch(){if(route().page==='home')$('#topic-results').innerHTML=topicCards();else if(route().page==='formulas')$('#formula-results').innerHTML=formulaResults();}
function bindPage(){$('#oral-ticket')?.addEventListener('change',e=>{newOral(e.target.value);location.hash='oral/'+e.target.value;});$('#search')?.addEventListener('input',e=>{query=e.target.value;updateSearch();});$('#topic-status')?.addEventListener('change',e=>{const t=course().topics.find(t=>t.id===e.target.dataset.topic);state.progress[topicKey(t)]=Number(e.target.value);save();$('.side-topics').innerHTML=sideTopics();toast('Готовность темы сохранена');});$('#deck-filter')?.addEventListener('change',e=>{makeDeck(e.target.value);render(false);});$('#oral-duration')?.addEventListener('change',e=>{oral.duration=Number(e.target.value);oral.remaining=oral.duration;render(false);});$('#progress-file')?.addEventListener('change',importProgress);}
document.addEventListener('click',e=>{const skip=e.target.closest('.skip');if(skip){e.preventDefault();$('#main').focus();$('#main').scrollIntoView({block:'start'});return;}const group=e.target.closest('[data-group]');if(group){viewGroup=group.dataset.group;const bar=$('.group-chips');bar.outerHTML=chips();updateSearch();return;}const tab=e.target.closest('[data-tab]');if(tab){const r=route();location.hash='topic/'+r.id+'/'+tab.dataset.tab;return;}const grade=e.target.closest('[data-grade]');if(grade){gradeCard(grade.dataset.grade);return;}const os=e.target.closest('[data-oral-status]');if(os){const t=course().topics.find(t=>t.id===oral.topicId);state.progress[topicKey(t)]=Number(os.dataset.oralStatus);save();$('.side-topics').innerHTML=sideTopics();toast('Самооценка сохранена');return;}const action=e.target.closest('[data-action]');if(!action)return;switch(action.dataset.action){case'menu':$('.workspace').inert=true;$('.sidebar').inert=false;$('.sidebar').classList.add('open');$('.mobile-scrim').classList.add('open');action.setAttribute('aria-expanded','true');$('.close-drawer').focus();break;case'close-menu':closeMenu();break;case'large-text':state.largeText=!state.largeText;save();document.body.classList.toggle('large-text',state.largeText);action.setAttribute('aria-pressed',String(state.largeText));break;case'reveal':flash.revealed=true;render(false);break;case'shuffle':makeDeck(flash?.filter||'all');render(false);break;case'all-cards':makeDeck('all');render(false);break;case'timer':toggleTimer();break;case'new-ticket':{const old=oral.topicId;newOral();if(course().topics.length>1){while(oral.topicId===old)newOral();}if(route().id){location.hash='oral';}else render(false);break;}case'oral-reveal':stopTimer();oral.show=!oral.show;render(false);break;case'save-plan':{const start=$('#plan-start').value,days=Number($('#plan-days').value);if(!/^\d{4}-\d{2}-\d{2}$/.test(start)||!Number.isFinite(+localDate(start))){toast('Выберите дату начала.');break;}state.plans[course().id]={start,days};save();render(false);toast('План обновлён');break;}case'export':download(JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2),'Прогресс-коллоквиум.json','application/json');break;case'import':$('#progress-file').click();break;case'reset':if(confirm('Удалить все отметки, интервалы карточек и планы на этом устройстве? Сначала можно экспортировать прогресс.')){state=baseState();save();flash=null;oral=null;render(false);toast('Прогресс сброшен');}break;case'offline':if(location.protocol==='file:'||window.OFFLINE_BUILD){e.preventDefault();download('<!doctype html>\n'+document.documentElement.outerHTML,'Физика.html','text/html');}break;}});
document.addEventListener('change',e=>{if(e.target.matches('[data-oral-check]')&&oral){oral.checks[Number(e.target.dataset.oralCheck)]=e.target.checked;if($('#oral-score'))$('#oral-score').textContent='Объяснил самостоятельно: '+oral.checks.filter(Boolean).length+' из '+oral.checks.length+' пунктов';}});
function closeMenu(){if($('.workspace'))$('.workspace').inert=false;const button=$('[data-action="menu"]');$('.sidebar')?.classList.remove('open');if($('.sidebar'))$('.sidebar').inert=window.matchMedia('(max-width:900px)').matches;$('.mobile-scrim')?.classList.remove('open');button?.setAttribute('aria-expanded','false');button?.focus();}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu();});
function download(data,name,type){const url=URL.createObjectURL(new Blob([data],{type:type+';charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function importProgress(e){const file=e.target.files[0];if(!file)return;if(file.size>2*1024*1024){toast('Файл слишком большой. Выберите экспорт прогресса JSON.');return;}try{const s=JSON.parse(await file.text());if(!validState(s))throw new Error('Неверный формат');const clean=baseState();for(const [key,value] of Object.entries(s.practice||{})){if(/^[a-zA-Z0-9:_-]+$/.test(key)&&['done','again'].includes(value))clean.practice[key]=value;}clean.course=COURSES.some(c=>c.id===s.course)?s.course:COURSES[0].id;clean.largeText=!!s.largeText;for(const c of COURSES){for(const t of c.topics){const key=`${c.id}:${t.id}`,v=s.progress[key];if(Number.isInteger(v)&&v>=0&&v<=3)clean.progress[key]=v;[...t.questions.map((_,i)=>'q'+i),...(t.learning?.practice||[]).map((_,i)=>'p'+i)].forEach(suffix=>{const k=`${key}:${suffix}`,card=s.cards[k];if(card&&Number.isInteger(card.streak)&&card.streak>=0&&card.streak<=3&&/^\d{4}-\d{2}-\d{2}$/.test(card.due)&&Number.isFinite(+localDate(card.due)))clean.cards[k]={streak:card.streak,due:card.due};});}const p=s.plans[c.id];if(p&&/^\d{4}-\d{2}-\d{2}$/.test(p.start)&&Number.isFinite(+localDate(p.start))&&Number.isInteger(p.days)&&p.days>=3&&p.days<=60)clean.plans[c.id]={start:p.start,days:p.days};if(c.topics.some(t=>t.id===s.last[c.id]))clean.last[c.id]=s.last[c.id];}if(!confirm('Заменить прогресс этого браузера данными из файла?'))return;state=clean;save();flash=null;oral=null;stopTimer();render(false);toast('Прогресс импортирован');}catch(err){toast('Не удалось импортировать. Нужен JSON-файл экспорта этого приложения.');}}
window.addEventListener('hashchange',()=>{query='';if(route().page!=='formulas'&&route().page!=='home')viewGroup='all';render();});
window.addEventListener('resize',()=>{const side=$('.sidebar');if(side)side.inert=window.matchMedia('(max-width:900px)').matches&&!side.classList.contains('open');});
if(!state.practiceRuleVersion){for(const c of COURSES){for(const t of c.topics){const keys=[...t.questions.map((_,i)=>`q${i}`),...(t.learning?.practice||[]).map((_,i)=>`p${i}`)];if(keys.length&&keys.every(k=>state.practice?.[`${c.id}:${t.id}:${k}`]==='done'))state.progress[`${c.id}:${t.id}`]=3;}}state.practiceRuleVersion=1;save();}
render(false);
if(!storageOK)toast('Локальное сохранение недоступно. Пользуйтесь экспортом прогресса.');




